import{_ as d,o as e,c as r,a2 as a}from"./chunks/framework.CFuv5BrO.js";const b=JSON.parse('{"title":"Hearth OS · 领域契约与状态机设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/Hearth-领域契约与状态机设计说明.md","filePath":"architecture/Hearth-领域契约与状态机设计说明.md","lastUpdated":null}'),o={name:"architecture/Hearth-领域契约与状态机设计说明.md"};function h(s,t,c,l,n,i){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="hearth-os-·-领域契约与状态机设计说明" tabindex="-1">Hearth OS · 领域契约与状态机设计说明 <a class="header-anchor" href="#hearth-os-·-领域契约与状态机设计说明" aria-label="Permalink to &quot;Hearth OS · 领域契约与状态机设计说明&quot;">​</a></h1><blockquote><p>本文只依据项目源码整理（<code>packages/core/src</code> 全部文件，以及 <code>apps/server/src/service.ts</code> 中构造视图的部分），未参考 <code>docs/</code> 与 <code>README.md</code>；文中不列举任何具体代码，括号内的文件名仅用于定位核对。 整理日期：2026-11-13</p></blockquote><p><strong>本文边界（避免与本套其它说明重复）</strong></p><table tabindex="0"><thead><tr><th>已讲过的内容</th><th>在哪份文档</th><th>本文的处理</th></tr></thead><tbody><tr><td>任务九状态与逐条合法转移、作为审批落地</td><td><a href="./判定审批机制说明.html">判定审批机制说明</a></td><td>不重列转移表，只讲状态机文件本身的组织与终态语义</td></tr><tr><td>85 张表结构</td><td><a href="./Hearth-存储设计说明.html">Hearth-存储设计说明</a></td><td>不展开</td></tr><tr><td>方法 / 技能 / 记忆资产记录类型</td><td><a href="./Hearth-自进化机制设计说明.html">Hearth-自进化机制设计说明</a></td><td>不展开</td></tr><tr><td>状态在调度器里如何推进</td><td><a href="./Hearth-任务执行调度器设计说明.html">Hearth-任务执行调度器设计说明</a></td><td>不展开</td></tr></tbody></table><p>本文只讲：<strong>这个零依赖的共享包是怎么组织「全系统共用词表」的，契约如何变成前端可消费的视图，以及默认值怎么合并</strong>。</p><hr><h2 id="_0-一句话总览" tabindex="-1">0. 一句话总览 <a class="header-anchor" href="#_0-一句话总览" aria-label="Permalink to &quot;0. 一句话总览&quot;">​</a></h2><p><code>@hearth/core</code> 是全仓唯一的共享词典：绝大多数文件只有类型与常量，没有业务逻辑；服务端用 <code>import type</code> 取形状、用常量数组取运行时白名单，前端再复用并扩展。整包零运行时依赖，入口只有四行导出。</p><hr><h2 id="_1-先定性-三个容易误解的地方" tabindex="-1">1. 先定性：三个容易误解的地方 <a class="header-anchor" href="#_1-先定性-三个容易误解的地方" aria-label="Permalink to &quot;1. 先定性：三个容易误解的地方&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>代码里的实际做法</th></tr></thead><tbody><tr><td>以为 <code>personal-agent.ts</code> 是「个人 Agent」的实现</td><td>它是契约类型的杂糅集合：本体、指代、上下文包、预备动作、订阅、后台工具、看门狗、入站决策的类型全在这里</td></tr><tr><td>以为九种任务状态里有若干终态</td><td>契约层显式只把「已完成」与「已取消」判为终态；失败与「可以继续」都能回退</td></tr><tr><td>以为常量数组就是全局唯一校验源</td><td>数组同时充当类型来源与运行时白名单，但服务端仍有若干处用集合、包含判断、模式枚举重复定义白名单</td></tr></tbody></table><hr><h2 id="_2-四个文件的分工" tabindex="-1">2. 四个文件的分工 <a class="header-anchor" href="#_2-四个文件的分工" aria-label="Permalink to &quot;2. 四个文件的分工&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>职责</th><th>是否含行为</th></tr></thead><tbody><tr><td><code>types.ts</code></td><td>主枚举、全部记录类型、设置默认值、健康/引导/上下文/主动式等返回契约</td><td>少量默认值生成函数</td></tr><tr><td><code>state.ts</code></td><td>状态机：转移表、可否转移、断言转移、中文标签、终态判定</td><td>是，全包唯一「有逻辑」的文件</td></tr><tr><td><code>dto.ts</code></td><td>前端列表与视图的形状</td><td>否</td></tr><tr><td><code>personal-agent.ts</code></td><td>个人 Agent 侧的结构化契约类型</td><td>否（少量枚举常量）</td></tr></tbody></table><hr><h2 id="_3-枚举体系-一套规律-三种变体" tabindex="-1">3. 枚举体系：一套规律，三种变体 <a class="header-anchor" href="#_3-枚举体系-一套规律-三种变体" aria-label="Permalink to &quot;3. 枚举体系：一套规律，三种变体&quot;">​</a></h2><p>主流写法是「常量数组 + 由数组派生的字面量联合类型」。这样同一个数组既在编译期约束类型，又在运行期充当合法值白名单，服务端可以直接拿它做参数校验。</p><p><strong>变体一：子集常量</strong>。例如「一等执行器」是七种执行器数组的子集，用于区分内建与外部执行器。</p><p><strong>变体二：全覆盖映射</strong>。用「键必须穷举所有状态」的映射类型做编译期校验，最典型的是九种任务状态的中文标签表，以及转移表本身；还有「每种触发器都要有策略」「每种执行器都要有开关」这类映射。一旦新增枚举值而忘了补映射，编译就会报错。</p><p><strong>变体三：纯字面量联合</strong>。少数概念（模型协议、搜索供应商、回收站种类、消息种类、差异范围等）没有常量数组，只有类型联合；因此这些值在运行期<strong>没有</strong>可直接复用的白名单。</p><p>枚举家族按领域大致分成：任务与运行、执行器与权限、审批与效果、目标与完成判定、来源与发件箱、设备与桌面、触发器与主动式、记忆（十余组）、方法与技能、同步与连接、维护、上下文、失败与交接、委派、渠道、以及 <code>personal-agent.ts</code> 里的本体与主动式契约。这是一张覆盖全系统的词表，而不是某个模块的内部枚举。</p><p>还有一类<strong>可辨识联合</strong>：失败处置用带分支标签的联合表达七种不同动作，每种动作带各自的附加字段，避免用一堆可选字段拼凑。</p><hr><h2 id="_4-状态机文件-小-但语义关键" tabindex="-1">4. 状态机文件：小，但语义关键 <a class="header-anchor" href="#_4-状态机文件-小-但语义关键" aria-label="Permalink to &quot;4. 状态机文件：小，但语义关键&quot;">​</a></h2><p>整个文件只有一个内部常量和四个导出：转移表、可否转移、断言转移（非法时抛出明确错误）、中文标签、终态判定。</p><p><strong>这里最值得记住的是终态定义</strong>：只有「已完成」与「已取消」是终态。失败状态可以回到排队或取消，「可以继续」也可以重新排队或运行。契约层与调度层的用词不完全一致——调度层把「可以继续」当作「已停下、需要人工唤醒」的暂停态处理（见<a href="./Hearth-任务执行调度器设计说明.html">Hearth-任务执行调度器设计说明</a>），理解时要把这两层分开。</p><hr><h2 id="_5-dto-把多条记录压成一张视图" tabindex="-1">5. DTO：把多条记录压成一张视图 <a class="header-anchor" href="#_5-dto-把多条记录压成一张视图" aria-label="Permalink to &quot;5. DTO：把多条记录压成一张视图&quot;">​</a></h2><p>服务端返回给前端的不是原始记录，而是聚合视图。最典型的是任务列表项：在任务记录之外附一份摘要，包含运行次数、最近耗时与用量、产物数、阶段、交付物清单、效果统计（总数与不确定数）、待审批编号。</p><p>实现上有个明确的性能设计：先一次性取回四张聚合映射（运行聚合、产物计数、效果聚合、待审批映射），再对任务列表逐条拼装，避免每条任务都回查数据库的 N+1 问题。</p><p>DTO 层还承担两件事：</p><ul><li><strong>补字段</strong>：用一个泛型混入类型给运行、审批、效果列表项补上任务标题，缺失时回退「未命名任务」。</li><li><strong>减字段与安全</strong>：产物列表项故意去掉服务端的绝对路径；审批列表在简要模式下会去掉目标与预览里的正文；事件窗口返回前后双向游标而非全量。</li></ul><hr><h2 id="_6-默认会话设置-三级回退与一个特例" tabindex="-1">6. 默认会话设置：三级回退与一个特例 <a class="header-anchor" href="#_6-默认会话设置-三级回退与一个特例" aria-label="Permalink to &quot;6. 默认会话设置：三级回退与一个特例&quot;">​</a></h2><p>默认设置会遍历全部七种执行器，逐个取「是否启用」，未列出的执行器一律为关闭；默认启用的是原生、Codex、Hermes 三种，审批模式为「必要时」，首选执行器为空。</p><p>合并补丁时：</p><table tabindex="0"><thead><tr><th>字段</th><th>合并规则</th></tr></thead><tbody><tr><td>各执行器开关</td><td>补丁值 → 当前值 → 关闭，三级回退</td></tr><tr><td>审批模式</td><td>补丁值 → 当前值</td></tr><tr><td>首选执行器</td><td><strong>只有显式传入空值才清空；未传表示「不修改」</strong></td></tr></tbody></table><p>最后一行与其它字段的空值合并语义不同：其它字段用「空则回退」，首选执行器用「是否显式提供」判断。这是刻意为之——用户想取消锁定执行器，必须明确传空，不能靠省略字段。</p><hr><h2 id="_7-只读代码才会发现的事实" tabindex="-1">7. 只读代码才会发现的事实 <a class="header-anchor" href="#_7-只读代码才会发现的事实" aria-label="Permalink to &quot;7. 只读代码才会发现的事实&quot;">​</a></h2><ol><li><code>personal-agent.ts</code> 名不副实，大量主动式与本体类型都在那里，不在主类型文件。</li><li>终态只有两个；失败与「可以继续」都能回退。</li><li>常量数组不是唯一校验源：服务端仍有集合、包含判断与模式枚举重复定义白名单，改枚举值要留意两处同步。</li><li>少数概念只有类型联合、没有运行期白名单数组。</li><li>产物列表项去掉绝对路径、简要审批去掉正文，是 DTO 层刻意的减负与防泄漏。</li><li>任务列表的聚合用四张映射一次性取回，不是逐条查询。</li></ol><hr><h2 id="_8-与其它模块的分界" tabindex="-1">8. 与其它模块的分界 <a class="header-anchor" href="#_8-与其它模块的分界" aria-label="Permalink to &quot;8. 与其它模块的分界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>内容</th></tr></thead><tbody><tr><td>输入</td><td>无（被全仓依赖）</td></tr><tr><td>输出</td><td>类型契约、枚举白名单、状态机函数、视图 DTO、默认设置</td></tr><tr><td>消费方</td><td>服务端各模块、事件与存储层、前端类型文件（复用并扩展）</td></tr><tr><td>不讲</td><td>表结构（存储）、状态如何推进（执行调度器）、审批如何落地（判定审批）、资产字段（自进化）</td></tr></tbody></table><hr><h2 id="附-源码定位索引" tabindex="-1">附：源码定位索引 <a class="header-anchor" href="#附-源码定位索引" aria-label="Permalink to &quot;附：源码定位索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想看什么</th><th>去哪找</th></tr></thead><tbody><tr><td>主枚举、记录类型、默认设置、健康与引导契约</td><td><code>packages/core/src/types.ts</code></td></tr><tr><td>状态机与终态判定</td><td><code>packages/core/src/state.ts</code></td></tr><tr><td>视图 DTO 形状</td><td><code>packages/core/src/dto.ts</code></td></tr><tr><td>本体 / 指代 / 上下文包 / 主动式契约</td><td><code>packages/core/src/personal-agent.ts</code></td></tr><tr><td>包入口</td><td><code>packages/core/src/index.ts</code></td></tr><tr><td>DTO 的实际聚合实现</td><td><code>apps/server/src/service.ts</code></td></tr><tr><td>前端复用与扩展</td><td><code>apps/web/src/lib/types.ts</code></td></tr></tbody></table>',47)])])}const _=d(o,[["render",h]]);export{b as __pageData,_ as default};
